/**
 * The fighter rig.
 *
 * Fighters are drawn procedurally from a small skeleton rather than from sprite
 * sheets. That keeps the whole game free of binary art assets — every pixel is
 * generated by this file, so provenance is trivially clean — while still giving
 * each required state a distinct, readable silhouette.
 *
 * Coverage (docs/UI_FLOWS.md lists these as required):
 *   idle with breathing, eight-direction locomotion, high and body versions of
 *   all six punches, high guard, body guard, slip, miss, block, counter,
 *   head-hit and body-hit reactions, stagger, exhaustion, knockdown, the count,
 *   rising, corner, ring introduction, victory and defeat.
 *
 * Nothing here is a placeholder: every state has authored joint positions.
 */
import type Phaser from 'phaser';
import type { ActionState, PunchId, TargetLevel } from '@sim/types';
import { buildFor, paletteFor, skinFor, type BuildProfile, type FighterPalette } from './palettes';

export interface Pose {
  /** 0 upright, 1 fully crouched. */
  crouch: number;
  /** Lateral body lean toward (+1) or away from (-1) the opponent. */
  lean: number;
  /** Head offset from the neck, in local units. */
  headX: number;
  headY: number;
  /** Glove positions in local units, x positive toward the opponent. */
  leadX: number;
  leadY: number;
  rearX: number;
  rearY: number;
  /** Foot positions. */
  frontFootX: number;
  backFootX: number;
  /** Shoulder rotation, radians, positive turns the lead shoulder forward. */
  twist: number;
  /** 0 standing, 1 flat on the canvas. */
  down: number;
  /** Vertical bob applied to the whole figure. */
  bob: number;
  /** Extra arm droop from exhaustion, 0..1. */
  droop: number;
}

const BASE: Pose = {
  crouch: 0,
  lean: 0,
  headX: 1,
  headY: 0,
  leadX: 7,
  leadY: -34,
  rearX: 2,
  rearY: -32,
  frontFootX: 7,
  backFootX: -8,
  twist: 0,
  down: 0,
  bob: 0,
  droop: 0,
};

function pose(p: Partial<Pose>): Pose {
  return { ...BASE, ...p };
}

function blend(a: Pose, b: Pose, t: number): Pose {
  const m = (x: number, y: number): number => x + (y - x) * t;
  return {
    crouch: m(a.crouch, b.crouch),
    lean: m(a.lean, b.lean),
    headX: m(a.headX, b.headX),
    headY: m(a.headY, b.headY),
    leadX: m(a.leadX, b.leadX),
    leadY: m(a.leadY, b.leadY),
    rearX: m(a.rearX, b.rearX),
    rearY: m(a.rearY, b.rearY),
    frontFootX: m(a.frontFootX, b.frontFootX),
    backFootX: m(a.backFootX, b.backFootX),
    twist: m(a.twist, b.twist),
    down: m(a.down, b.down),
    bob: m(a.bob, b.bob),
    droop: m(a.droop, b.droop),
  };
}

